pages={}
def header(active):
    return '<div class="top"><div class="shell nav"><a class="brand" href="index.html"><span class="mark">S</span><span>SPOTTA <small>HUMAN CAPITAL ECOSYSTEM</small></span></a><nav class="links">'+''.join(f'<a class="{"active" if f==active else ""}" href="{f}">{label}</a>' for f,label in nav)+'</nav></div></div>'
def footer(): return '<footer class="footer"><div class="shell footer-inner"><div><b>SPOTTA / HUMAN CAPITAL ECOSYSTEM</b><br>طرح پیشنهادی برای توسعه سرمایه انسانی، تجربه کارکنان و مسیرهای رشد</div><div>نسخه مفهومی برای بررسی مدیریتی <span>•</span> اعداد و اهداف اجرایی نیازمند اعتبارسنجی هستند.</div></div></footer>'
def page(active,body,title):
    return '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="طرح راهبردی اکوسیستم سرمایه انسانی اسپوتا"><title>'+title+' | اسپوتا</title><link rel="stylesheet" href="assets/style.css"></head><body>'+header(active)+body+footer()+'</body></html>'

pages['index.html']=page('index.html','''<header class="hero"><div class="shell hero-grid"><div><div class="eyebrow">پیشنهاد راهبردی برای اسپوتا هلدینگ</div><h1>اسپوتا؛ جایی برای <em>رشد انسان</em> و تکثیر توانمندی</h1><p class="lead">طرحی برای تبدیل تجربه کار در اسپوتا به یک اکوسیستم زنده؛ جایی که کارکنان رشد می‌کنند، دانش را به هم منتقل می‌کنند، خانواده‌ها ارزش بیشتری دریافت می‌کنند و نسل بعدی برای ورود آگاهانه به بازار کار آماده می‌شود.</p><a class="btn" href="strategy.html">مشاهده معماری راهبردی ←</a><a class="btn outline" href="roadmap.html">نقشه اجرای پیشنهادی</a></div><div class="hero-art"><div class="art-label">HUMAN CAPITAL / MULTIPLIER MODEL</div><div class="big-num">1000<span style="font-size:26px;color:#fff">+</span></div><h3>نفر؛ یک شبکه بزرگ از تجربه، مهارت و ظرفیت رشد</h3><div class="art-bottom"><span class="pill">کارکنان</span><span class="pill">خانواده‌ها</span><span class="pill">نسل آینده</span><span class="pill">شبکه استعداد</span></div></div></div></header>
<section class="section"><div class="shell"><div class="section-head"><div><div class="kicker">THE BIG IDEA</div><h2>از مزایای پراکنده تا یک سیستم رشد</h2><p class="section-intro">پیشنهاد، اضافه کردن چند برنامه مناسبتی نیست؛ ساختن سازوکاری است که یادگیری، پیشرفت، مشارکت و انتقال دانش را به تجربه‌ای قابل لمس تبدیل کند.</p></div></div><div class="grid four"><article class="card"><div class="iconbox">↗</div><h3>رشد فردی</h3><p>هر فرد بداند امروز کجاست، قدم بعدی چیست و برای رسیدن به آن چه مهارت‌هایی لازم دارد.</p></article><article class="card"><div class="iconbox">⇄</div><h3>تکثیر دانش</h3><p>تجربه افراد از دانش شخصی به سرمایه مشترک سازمان تبدیل شود.</p></article><article class="card"><div class="iconbox">⌂</div><h3>ارزش برای خانواده</h3><p>فرصت‌های آموزشی و مهارتی برای خانواده و فرزندان کارکنان تعریف شود.</p></article><article class="card"><div class="iconbox">◎</div><h3>مسیر شغلی نسل بعد</h3><p>آموزش با تجربه واقعی و مسیر دسترسی به فرصت‌های شغلی پیوند بخورد.</p></article></div><div class="statrow"><div class="stat"><strong>۱۰۰۰</strong><span>کارمند در نقطه شروع اکوسیستم</span></div><div class="stat"><strong>۳</strong><span>جامعه اصلی: کارکنان، خانواده، نسل آینده</span></div><div class="stat"><strong>۹۰ روز</strong><span>برای شناخت و اجرای پایلوت اولیه</span></div><div class="stat"><strong>۱ سال</strong><span>برای استقرار مرحله‌ای و ارزیابی</span></div></div></div></section>
<section class="section gray"><div class="shell split"><div><div class="kicker">STRATEGIC PRINCIPLE</div><h2>اسپوتا قرار نیست مالک آینده آدم‌ها باشد؛ باید به ساختن آینده آن‌ها کمک کند.</h2><p class="section-intro">این اصل باید در تصمیم‌های واقعی دیده شود: مسیر رشد شفاف، فرصت یادگیری منصفانه، شنیده‌شدن پیشنهادها، پاداش برای مشارکت و دسترسی به فرصت‌های واقعی.</p><div class="callout"><strong>اصل مرکزی</strong><br>هر انسانی که وارد اکوسیستم اسپوتا می‌شود، باید امکان خروج با دانش، توانمندی و ارزش بیشتر را داشته باشد؛ چه مسیر حرفه‌ای‌اش در اسپوتا ادامه پیدا کند، چه در آینده به مسیر دیگری برسد.</div></div><div class="visualbox"><div class="kicker">THE MULTIPLIER LOOP</div><div class="flow"><div class="step"><strong>یاد می‌گیرد</strong><span>Learn</span></div><div class="step"><strong>رشد می‌کند</strong><span>Grow</span></div><div class="step"><strong>منتقل می‌کند</strong><span>Teach</span></div></div><div class="flow"><div class="step"><strong>دیده می‌شود</strong><span>Recognize</span></div><div class="step"><strong>دیگری را توانمند می‌کند</strong><span>Multiply</span></div></div><p class="small">چرخه پیشنهادی: یادگیری باید به توانمندی، انتقال دانش و اثر قابل مشاهده منجر شود.</p></div></div></section>
<section class="section"><div class="shell"><div class="section-head"><div><div class="kicker">EXPLORE THE PLAN</div><h2>معماری پیشنهادی در یک نگاه</h2></div></div><div class="grid three"><a class="card" href="strategy.html"><div class="number">01</div><h3>راهبرد و منطق کسب‌وکار</h3><p>چرا این اکوسیستم، چه ارزشی ایجاد می‌کند و کدام مسائل را هدف می‌گیرد.</p></a><a class="card" href="employee.html"><div class="number">02</div><h3>تجربه و رشد کارکنان</h3><p>مسیر رشد، گذرنامه مهارتی، جابه‌جایی داخلی، صدا و قدردانی.</p></a><a class="card" href="skills.html"><div class="number">03</div><h3>اقتصاد مهارت داخلی</h3><p>کشف مهارت‌های پنهان و اتصال افراد به یکدیگر برای یادگیری و آموزش.</p></a><a class="card" href="academy.html"><div class="number">04</div><h3>آکادمی و خانواده</h3><p>مسیر آموزش، تجربه، گواهی و دسترسی مشروط به فرصت‌های شغلی برای نسل بعد.</p></a><a class="card" href="roadmap.html"><div class="number">05</div><h3>نقشه راه یک‌ساله</h3><p>از کشف نیازها تا پایلوت، توسعه و تصمیم برای مقیاس‌دادن.</p></a><a class="card" href="metrics.html"><div class="number">06</div><h3>حاکمیت و سنجش</h3><p>نقش‌ها، شاخص‌ها، ریسک‌ها و شروط موفقیت.</p></a></div></div></section>''','نمای کلی')

pages['strategy.html']=page('strategy.html','''<header class="pagehero"><div class="shell"><div class="eyebrow">01 / STRATEGY</div><h1>معماری راهبردی اکوسیستم</h1><p>هدف، ساختن تجربه‌ای منسجم از رشد و مشارکت است؛ با پیوند دادن توسعه کارکنان، خانواده و نسل آینده به یک چرخه ارزش‌آفرین.</p></div></header><section class="section"><div class="shell"><div class="quote">«اسپوتا فقط محل اشتغال نیست؛ می‌تواند جایی باشد که <span>سرمایه انسانی ساخته و تکثیر می‌شود.</span>»</div><div class="grid two" style="margin-top:30px"><article class="card dark"><div class="kicker">VISION</div><h3>چشم‌انداز</h3><p>تبدیل‌شدن به سازمانی که در آن افراد امکان یادگیری، رشد، اثرگذاری و انتقال دانش دارند و این ظرفیت از کارکنان به خانواده‌ها و نسل بعد گسترش پیدا می‌کند.</p></article><article class="card"><div class="kicker">MISSION</div><h3>مأموریت</h3><p>ایجاد مسیرهای روشن برای رشد شغلی، شناسایی مهارت‌های پنهان، تسهیل یادگیری همتا‌به‌همتا، شنیدن صدای کارکنان و ساختن مسیرهای معتبر برای آماده‌سازی استعدادهای آینده.</p></article></div><div class="section-head" style="margin-top:46px"><div><div class="kicker">VALUE ARCHITECTURE</div><h2>چهار لایه ارزش</h2></div></div><div class="flow"><div class="step"><strong>کارمند</strong><span>رشد، مهارت، مسیر شغلی</span></div><div class="step"><strong>خانواده</strong><span>آموزش، امنیت آینده، مشارکت</span></div><div class="step"><strong>نسل آینده</strong><span>مهارت، تجربه، آمادگی شغلی</span></div><div class="step"><strong>سازمان و صنعت</strong><span>استعداد، دانش، کیفیت، نوآوری</span></div></div><h2>ارزش پیشنهادی برای هر ذی‌نفع</h2><div class="tablewrap"><table><thead><tr><th>ذی‌نفع</th><th>ارزش پیشنهادی</th><th>نشانه قابل مشاهده</th></tr></thead><tbody><tr><td>کارکنان تولید</td><td>مسیر رشد روشن، آموزش کاربردی، دیده‌شدن تجربه</td><td>نقشه مهارت، گواهی عملی، فرصت تجربه واحد دیگر</td></tr><tr><td>کارکنان اداری و تخصصی</td><td>توسعه تخصص، پروژه‌های بین‌واحدی، منتورینگ</td><td>برنامه رشد، پروژه واقعی، ثبت دستاورد</td></tr><tr><td>سرپرستان و مدیران</td><td>تیم توانمندتر، انتقال دانش، بهبود عملکرد</td><td>آموزش حین کار، جانشین‌پروری، کاهش خطا</td></tr><tr><td>خانواده‌ها</td><td>دسترسی به فرصت‌های آموزشی و مهارتی</td><td>برنامه‌های خانواده، کارگاه‌ها، مسیر نسل آینده</td></tr><tr><td>جوانان و فرزندان کارکنان</td><td>مهارت قابل ارزیابی، تجربه و دسترسی به فرصت شغلی</td><td>پروژه عملی، کارآموزی، گواهی معتبر</td></tr><tr><td>اسپوتا</td><td>جذب و نگهداشت بهتر، دانش ماندگار، برند کارفرمایی معتبر</td><td>ارتقای داخلی، پیشنهادهای اجراشده، معرفی نیروی واجدشرایط</td></tr></tbody></table></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">DESIGN PRINCIPLES</div><h2>اصول طراحی سیستم</h2></div></div><div class="grid three"><article class="card"><h3>واقعی، نه نمایشی</h3><p>هر وعده باید به تجربه، فرآیند یا فرصت واقعی متصل باشد.</p></article><article class="card"><h3>مکمل حقوق، نه جایگزین آن</h3><p>آموزش و مزایا نباید پوششی برای جبران حقوق نامناسب باشند.</p></article><article class="card"><h3>رشد چندمسیره</h3><p>رشد می‌تواند تخصصی، عمودی یا بین‌واحدی باشد؛ نه فقط مدیریت.</p></article><article class="card"><h3>داوطلبانه و منصفانه</h3><p>مشارکت در آموزش و برنامه‌های خارج از ساعت کاری باید داوطلبانه و منصفانه جبران شود.</p></article><article class="card"><h3>قابل سنجش</h3><p>تعداد فعالیت‌ها کافی نیست؛ اثر بر مهارت، کیفیت، بهره‌وری و تجربه باید سنجیده شود.</p></article><article class="card"><h3>مرحله‌ای و قابل اصلاح</h3><p>ابتدا پایلوت کوچک، سپس توسعه بر اساس شواهد واقعی.</p></article></div></div></section>''','استراتژی')

pages['employee.html']=page('employee.html','''<header class="pagehero"><div class="shell"><div class="eyebrow">02 / EMPLOYEE EXPERIENCE</div><h1>تجربه کارکنان؛ از ورود تا رشد</h1><p>سیستم باید برای نیروی خط تولید، تکنسین، کارمند اداری، متخصص و مدیر قابل استفاده باشد؛ با مسیرها و ابزارهای متناسب با واقعیت هر نقش.</p></div></header><section class="section"><div class="shell"><div class="section-head"><div><div class="kicker">GROWTH PASSPORT</div><h2>گذرنامه رشد هر کارمند</h2><p class="section-intro">یک پرونده روشن و به‌روز از وضعیت فعلی، مسیر بعدی، فاصله مهارتی و تجربه‌های رشد؛ نه صرفاً فرم ارزیابی سالانه.</p></div></div><div class="grid two"><div class="card"><h3>محتوای گذرنامه</h3><ul><li>نقش فعلی و مهارت‌های تأییدشده</li><li>نقش بعدی یا مسیر تخصصی احتمالی</li><li>مهارت‌های موردنیاز و فاصله تا مقصد</li><li>دوره‌ها، گواهی‌ها و ارزیابی‌های عملی</li><li>پروژه‌ها، تجربه‌های بین‌واحدی و منتورینگ</li><li>گفت‌وگوهای رشد و هدف‌های دوره بعد</li></ul></div><div class="visualbox"><div class="kicker">نمونه مسیر شغلی</div><div class="flow"><div class="step"><strong>اپراتور</strong><span>وضعیت فعلی</span></div><div class="step"><strong>اپراتور ارشد</strong><span>مهارت و کیفیت</span></div><div class="step"><strong>سرپرست خط</strong><span>رهبری و ایمنی</span></div></div><div class="barrow"><span>مهارت فنی</span><div class="bar"><i style="width:80%"></i></div><b>۸۰٪</b></div><div class="barrow"><span>حل مسئله</span><div class="bar"><i style="width:55%"></i></div><b>۵۵٪</b></div><div class="barrow"><span>رهبری تیم</span><div class="bar"><i style="width:25%"></i></div><b>۲۵٪</b></div><p class="small">نمایش شماتیک است؛ درصدها نمونه‌اند و داده واقعی اسپوتا نیستند.</p></div></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">EMPLOYEE JOURNEY</div><h2>تجربه ۹۰ روز اول</h2></div></div><div class="grid four"><article class="card"><div class="number">هفته ۱</div><h3>شناخت سازمان</h3><p>ایمنی، فرهنگ، ساختار، افراد کلیدی و انتظارات نقش.</p></article><article class="card"><div class="number">ماه ۱</div><h3>تسلط به نقش</h3><p>انتظارات روشن، همراه یا Buddy و بازخورد اولیه.</p></article><article class="card"><div class="number">ماه ۲</div><h3>یک مهارت جدید</h3><p>تمرین و ارزیابی یک مهارت مرتبط با شغل.</p></article><article class="card"><div class="number">ماه ۳</div><h3>اولین دستاورد</h3><p>اجرای مستقل یک کار یا بهبود کوچک و گفت‌وگوی رشد.</p></article></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">VOICE & TRUST</div><h2>«گفتید، پیگیری کردیم»</h2><p class="section-intro">جمع‌آوری نظر بدون پاسخ و اقدام، اعتماد را تخریب می‌کند. هر پیشنهاد باید وضعیت قابل پیگیری داشته باشد.</p></div></div><div class="flow"><div class="step"><strong>دریافت شد</strong><span>ثبت پیشنهاد</span></div><div class="step"><strong>در بررسی</strong><span>مالک و زمان پاسخ</span></div><div class="step"><strong>تأیید شد</strong><span>برنامه اقدام</span></div><div class="step"><strong>اجرا شد</strong><span>اثر و نتیجه</span></div><div class="step"><strong>رد با دلیل</strong><span>شفافیت تصمیم</span></div></div><div class="grid three"><article class="card"><h3>صدای کارکنان</h3><p>کانال امن برای پیشنهادها، مسائل محیط کار و ایده‌های بهبود؛ با امکان مشارکت حضوری و غیر دیجیتال.</p></article><article class="card"><h3>تحرک داخلی</h3><p>فرصت‌های کوتاه‌مدت پروژه‌ای یا تجربه واحد دیگر برای کشف استعدادهای پنهان.</p></article><article class="card"><h3>همراهی و منتورینگ</h3><p>Buddy برای تازه‌وارد، Mentor برای توسعه مهارت و Sponsor برای حمایت از استعدادهای کلیدی.</p></article></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">RECOGNITION</div><h2>قدردانی بر اساس اثر واقعی</h2></div></div><div class="grid three"><article class="card orange"><h3>اثر بر افراد</h3><p>کمک به همکار، منتورینگ، آموزش و همراهی نیروی جدید.</p></article><article class="card"><h3>اثر بر کیفیت و ایمنی</h3><p>کاهش خطا، پیشگیری از خطر، ارتقای کیفیت و نظم.</p></article><article class="card"><h3>اثر بر کسب‌وکار</h3><p>کاهش ضایعات، صرفه‌جویی زمان، حل مسئله و پیشنهاد اجراشده.</p></article></div><p class="notice" style="margin-top:22px">نکته اجرایی: حضور در شبکه‌های اجتماعی یا ساخت برند شخصی نباید اجباری باشد. برای کارکنان تخصصی می‌توان توسعه حضور حرفه‌ای را پیشنهاد کرد؛ برای نیروهای فنی، ثبت مهارت، تجربه دستگاه، پروژه و گواهی ممکن است ارزشمندتر باشد.</p></div></section>''','تجربه کارکنان')

pages['skills.html']=page('skills.html','''<header class="pagehero"><div class="shell"><div class="eyebrow">03 / INTERNAL SKILL ECONOMY</div><h1>اقتصاد مهارت؛ دانشی که در سازمان جریان پیدا می‌کند</h1><p>پیش از خرید آموزش‌های گسترده یا ساخت پلتفرم، باید بدانیم چه مهارت‌هایی همین حالا در میان کارکنان وجود دارد و چطور می‌توان آن‌ها را به‌صورت ایمن و باکیفیت به اشتراک گذاشت.</p></div></header><section class="section"><div class="shell"><div class="quote">پرسش آغازین: <span>«چه چیزی بلدی که در شرح شغلت نوشته نشده؟»</span></div><div class="grid two" style="margin-top:26px"><div class="card dark"><div class="kicker">STEP 01</div><h3>Skill Census / سرشماری مهارت</h3><p>فرم کوتاه برای کشف مهارت‌های حرفه‌ای و شخصی: مکانیک، جوشکاری، کار با دستگاه، Excel، زبان، عکاسی، طراحی، فروش، تعمیرات، ورزش یا آموزش.</p></div><div class="card"><div class="kicker">STEP 02</div><h3>Skill Map / نقشه مهارت</h3><p>دسته‌بندی مهارت‌ها بر اساس سطح، علاقه به آموزش، امکان استفاده در کار، نیاز بازار داخلی و شرایط ایمنی؛ با دسترسی کنترل‌شده به اطلاعات.</p></div></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">HOW IT WORKS</div><h2>چرخه آموزش همتا‌به‌همتا</h2></div></div><div class="flow"><div class="step"><strong>من بلدم</strong><span>پروفایل مدرس</span></div><div class="step"><strong>من می‌خواهم یاد بگیرم</strong><span>ثبت تقاضا</span></div><div class="step"><strong>تطبیق</strong><span>زمان، سطح، ظرفیت</span></div><div class="step"><strong>آموزش</strong><span>جلسه یا کارگاه</span></div><div class="step"><strong>ارزیابی</strong><span>تمرین و بازخورد</span></div><div class="step"><strong>قدردانی</strong><span>ثبت اثر و پاداش</span></div></div><div class="grid three"><article class="card"><h3>Skill Sharer</h3><p>فردی که مهارتی را بلد است و می‌تواند به یک یا چند نفر منتقل کند؛ با راهنمای آموزشی ساده.</p></article><article class="card"><h3>Internal Trainer</h3><p>فردی که آموزش را تجربه کرده، بازخورد گرفته و کیفیت انتقال دانشش ارزیابی شده است.</p></article><article class="card"><h3>Certified Trainer</h3><p>مدرس تأییدشده برای موضوع‌های مشخص؛ با محتوای استاندارد، ارزیابی و بازبینی دوره‌ای.</p></article></div><div class="callout"><strong>دو مسیر را از هم جدا نگه داریم</strong><br>«چه چیزی می‌توانم آموزش بدهم؟» با «برای رشد شغلی خودم چه چیزی باید یاد بگیرم؟» یک سؤال نیست. یک فرد ممکن است مدرس مکانیک باشد، اما برای رشد خودش به مهارت سرپرستی یا کنترل کیفیت نیاز داشته باشد.</div><div class="section-head" style="margin-top:42px"><div><div class="kicker">REWARDS</div><h2>امتیازدهی که به ارزش واقعی وصل است</h2><p class="section-intro">امتیاز نباید به بازی کودکانه یا رقابت بر سر تعداد فعالیت‌ها تبدیل شود؛ باید رفتارهای مفید را به فرصت و پاداش ملموس وصل کند.</p></div></div><div class="tablewrap"><table><thead><tr><th>رفتار</th><th>منطق امتیاز</th><th>شرط کیفیت</th></tr></thead><tbody><tr><td>ثبت پیشنهاد</td><td>امتیاز مشارکت</td><td>پیشنهاد روشن و قابل بررسی</td></tr><tr><td>پیشنهاد پذیرفته‌شده</td><td>امتیاز بیشتر</td><td>تأیید مالک فرایند</td></tr><tr><td>اجرای پیشنهاد</td><td>پاداش اثر</td><td>ثبت نتیجه یا صرفه‌جویی</td></tr><tr><td>آموزش همکار</td><td>امتیاز انتقال دانش</td><td>حضور، ارزیابی و رضایت یادگیرنده</td></tr><tr><td>گذراندن دوره و گواهی</td><td>اعتبار رشد</td><td>ارتباط با مسیر رشد یا نیاز سازمان</td></tr><tr><td>منتورینگ نیروی جدید</td><td>اعتبار همراهی</td><td>بازخورد نیروی جدید و مدیر</td></tr><tr><td>کمک به واحد دیگر</td><td>اعتبار همکاری</td><td>تأیید دو واحد و خروجی مشخص</td></tr></tbody></table></div><div class="grid two" style="margin-top:22px"><article class="card orange"><h3>پاداش‌های قابل بررسی</h3><p>اعتبار آموزشی، کتاب و تجهیزات یادگیری، کارگاه تخصصی، امکانات ورزشی، هدیه آموزشی خانواده، فرصت شرکت در پروژه یا تقدیر حرفه‌ای.</p></article><article class="card"><h3>Learning Wallet</h3><p>اعتبار سالانه توسعه فردی برای دوره‌ها یا منابع تأییدشده؛ با سقف بودجه، معیار شفاف و امکان انتخاب متناسب با مسیر رشد.</p></article></div><p class="notice" style="margin-top:22px">اگر آموزش خارج از ساعت کاری انجام می‌شود، مشارکت باید داوطلبانه باشد و جبران خدمت، پرداخت، بیمه، مسئولیت و الزامات قانونی پیش از اجرا با HR و واحد حقوقی بررسی شود. آموزش فنی با دستگاه نیز نیازمند نظارت، تجهیزات ایمنی و مجوز مشخص است.</p></div></section>''','اقتصاد مهارت')

pages['academy.html']=page('academy.html','''<header class="pagehero"><div class="shell"><div class="eyebrow">04 / FAMILY & NEXT GENERATION</div><h1>آکادمی مهارت اسپوتا؛ از یادگیری تا آمادگی شغلی</h1><p>فرصت‌های آموزشی برای خانواده‌ها و نسل آینده، با پیوندی روشن میان آموزش، ارزیابی عملی، تجربه واقعی و دسترسی منصفانه به فرصت‌های شغلی.</p></div></header><section class="section"><div class="shell"><div class="quote">ارزش واقعی آکادمی، <span>قابلیت اشتغال‌پذیری</span> است؛ نه صرفاً صدور گواهی.</div><div class="flow" style="margin-top:30px"><div class="step"><strong>مهارت</strong><span>آموزش کاربردی</span></div><div class="step"><strong>ارزیابی</strong><span>آزمون عملی</span></div><div class="step"><strong>گواهی</strong><span>اعتبار قابل اثبات</span></div><div class="step"><strong>تجربه</strong><span>پروژه یا کارآموزی</span></div><div class="step"><strong>مسیر شغلی</strong><span>اسپوتا یا صنعت</span></div></div><div class="grid three"><article class="card"><div class="number">01</div><h3>SPOTTA EMPLOYEE</h3><p>رشد کارکنان فعلی: مسیر شغلی، مهارت‌های تخصصی، منتورینگ و جابه‌جایی داخلی.</p></article><article class="card orange"><div class="number">02</div><h3>SPOTTA NEXT</h3><p>فرزندان کارکنان و نسل جوان: آشنایی با حرفه‌ها، آموزش مهارت، کارگاه‌های ایمن و راهنمایی مسیر آینده.</p></article><article class="card"><div class="number">03</div><h3>SPOTTA TALENT</h3><p>در مرحله توسعه، جذب استعدادهای بیرون از شرکت و همکاری با مدارس فنی، دانشگاه‌ها و شرکای صنعتی.</p></article></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">PARENT VALUE</div><h2>ارزش روشن برای خانواده‌ها</h2></div></div><div class="split"><div><p>یکی از نگرانی‌های جدی والدین، آینده شغلی فرزند بعد از مدرسه یا دانشگاه است. آکادمی می‌تواند این نگرانی را با یک مسیر قابل مشاهده پاسخ دهد: یادگیری مهارت، اثبات توانایی، تجربه و دسترسی به فرصت‌ها.</p><ul><li>کارگاه‌های فنی و حرفه‌ای متناسب با سن</li><li>طراحی، مهارت‌های دیجیتال، زبان و مهارت‌های کاربردی</li><li>بازدید کنترل‌شده از محیط کار و آشنایی با مشاغل</li><li>پروژه عملی و پرونده مهارتی برای هر فراگیر</li><li>مشاوره مسیر تحصیلی و شغلی</li><li>رویداد خانواده، نمایش دستاوردها و مسابقه مهارت</li></ul></div><div class="visualbox"><div class="kicker">CAREER ACCESS MODEL</div><div class="barrow"><span>آموزش</span><div class="bar"><i style="width:100%"></i></div><b>۱</b></div><div class="barrow"><span>ارزیابی</span><div class="bar"><i style="width:85%"></i></div><b>۲</b></div><div class="barrow"><span>پروژه واقعی</span><div class="bar"><i style="width:70%"></i></div><b>۳</b></div><div class="barrow"><span>کارآموزی</span><div class="bar"><i style="width:55%"></i></div><b>۴</b></div><div class="barrow"><span>فرصت شغلی</span><div class="bar"><i style="width:40%"></i></div><b>۵</b></div><p class="small">این نمودار مراحل مسیر را نشان می‌دهد، نه احتمال آماری استخدام.</p></div></div><div class="callout"><strong>پیشنهاد درباره استخدام فارغ‌التحصیلان</strong><br>فارغ‌التحصیل واجدشرایط آکادمی می‌تواند از «مسیر اولویت‌دار بررسی برای فرصت‌های شغلی مرتبط» بهره‌مند شود. این مسیر باید معیارهای شفاف، ارزیابی عملی، رفتار حرفه‌ای، الزامات ایمنی، ظرفیت واقعی شغلی و ضوابط استخدام را رعایت کند؛ نباید به‌عنوان تضمین استخدام همگانی معرفی شود.</div><h2 style="margin-top:40px">گذرنامه مهارتی نسل آینده</h2><div class="grid four"><article class="card"><h3>مهارت‌ها</h3><p>چه توانایی‌هایی را یاد گرفته است؟</p></article><article class="card"><h3>ارزیابی</h3><p>در چه سطحی توانایی خود را اثبات کرده؟</p></article><article class="card"><h3>تجربه</h3><p>چه پروژه یا تمرین واقعی انجام داده؟</p></article><article class="card"><h3>مسیر بعدی</h3><p>چه دوره، کارآموزی یا فرصت شغلی به او می‌خورد؟</p></article></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">FAMILY ECOSYSTEM</div><h2>برنامه‌های مکمل خانواده</h2></div></div><div class="grid three"><article class="card"><h3>یادگیری خانواده</h3><p>کارگاه‌های کاربردی، آموزش مالی یا دیجیتال و دسترسی به دوره‌های منتخب.</p></article><article class="card"><h3>رویداد و مشارکت</h3><p>روز خانواده، بازدید برنامه‌ریزی‌شده، نمایش پروژه‌های فرزندان و مسابقه مهارت.</p></article><article class="card"><h3>فرصت‌های حمایتی</h3><p>تخفیف آموزشی، اعتبار یادگیری یا کمک‌هزینه‌های هدفمند بر اساس سیاست‌های مصوب.</p></article></div><p class="notice" style="margin-top:22px">شروع آکادمی برای کودکان و نوجوانان به طراحی متناسب با سن، رضایت والدین، حفاظت از کودک، ایمنی، بیمه و مسئولیت حقوقی نیاز دارد. صدور گواهی معتبر نیز باید بر اساس ارزیابی واقعی و در صورت نیاز با شریک آموزشی دارای صلاحیت انجام شود. عنوان «آکادمی» در این سند مفهومی است و جایگزین مجوزهای لازم برای مدرسه یا مرکز رسمی آموزشی نیست.</p></div></section>''','آکادمی اسپوتا')

pages['roadmap.html']=page('roadmap.html','''<header class="pagehero"><div class="shell"><div class="eyebrow">05 / IMPLEMENTATION ROADMAP</div><h1>از ایده تا اجرا؛ نقشه راه یک‌ساله</h1><p>اجرای موفق از ساخت اپلیکیشن یا راه‌اندازی آکادمی آغاز نمی‌شود؛ از شناخت کارکنان، انتخاب مسئله‌های واقعی و آزمایش محدود شروع می‌شود.</p></div></header><section class="section"><div class="shell"><div class="grid two"><article class="card dark"><div class="kicker">FIRST 90 DAYS</div><h3>هدف پایلوت</h3><p>اعتبارسنجی تقاضا، کشف مهارت‌های موجود، آزمون پاسخ‌گویی به پیشنهادها و سنجش امکان آموزش داخلی با یک گروه کوچک و متنوع.</p></article><article class="card"><div class="kicker">PILOT SIZE</div><div class="number">۳۰–۵۰ نفر</div><p>گروه آزمایشی پیشنهادی از تولید، واحدهای اداری، سرپرستان و نیروهای جوان؛ عدد نهایی بر اساس ساختار واقعی سازمان تعیین شود.</p></article></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">PHASE PLAN</div><h2>مراحل اجرایی</h2></div></div><div class="timeline"><div class="timeitem"><h3>ماه ۱ — شنیدن و کشف</h3><p>مصاحبه و نظرسنجی، سرشماری مهارت، بررسی مسیرهای شغلی، شناخت نیازهای خانواده و مرور مزایای فعلی.</p><span class="tag">خروجی: نقشه نیازها و مهارت‌ها</span><span class="tag">مالک: HR + مدیران + ارتباطات</span></div><div class="timeitem"><h3>ماه ۲ — طراحی حداقل سیستم</h3><p>انتخاب چند شغل کلیدی برای نقشه رشد، طراحی فرم پیشنهادها، تعریف قواعد Skill Exchange و طراحی روایت‌های واقعی کارکنان.</p><span class="tag">خروجی: Growth Map + Voice System</span></div><div class="timeitem"><h3>ماه ۳ — اجرای پایلوت</h3><p>راه‌اندازی آموزش داخلی با حدود ۱۰ مدرس و ۳۰ یادگیرنده به‌عنوان فرض اولیه، آزمون تطبیق مهارت و ثبت بازخورد؛ اجرای یک چرخه «گفتید، پیگیری کردیم».</p><span class="tag">خروجی: گزارش پایلوت و تصمیم مقیاس‌پذیری</span></div><div class="timeitem"><h3>ماه ۴ تا ۶ — تثبیت</h3><p>اصلاح سیستم، گسترش نقشه رشد به نقش‌های بیشتر، راه‌اندازی گذرنامه رشد، تعریف قدردانی مبتنی بر اثر و آغاز فرصت‌های تجربه بین‌واحدی.</p><span class="tag">خروجی: نسخه عملیاتی ۱</span></div><div class="timeitem"><h3>ماه ۷ تا ۹ — خانواده و نسل آینده</h3><p>نیازسنجی والدین و جوانان، انتخاب یک یا دو حوزه مهارتی برای آزمایش، بررسی شریک آموزشی و تعریف چارچوب مسیر دسترسی به فرصت شغلی.</p><span class="tag">خروجی: طرح آزمایشی SPOTTA NEXT</span></div><div class="timeitem"><h3>ماه ۱۰ تا ۱۲ — ارزیابی و توسعه</h3><p>مقایسه شاخص‌های قبل و بعد، سنجش هزینه و اثر، تصمیم درباره توسعه، پلتفرم دیجیتال، آکادمی یا مشارکت با نهادهای آموزشی.</p><span class="tag">خروجی: نقشه راه سال دوم</span></div></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">RESEARCH QUESTIONS</div><h2>پرسش‌های مصاحبه اولیه</h2></div></div><div class="grid two"><article class="card"><ul><li>اگر سه سال دیگر در اسپوتا باشی، دوست داری چه چیزی تغییر کرده باشد؟</li><li>چه چیزی باعث می‌شود بمانی؟ چه چیزی ممکن است باعث رفتنت شود؟</li><li>دوست داری چه مهارتی یاد بگیری؟</li><li>چه چیزی بلدی که سازمان از آن استفاده نمی‌کند؟</li><li>دوست داری مدتی در کدام واحد تجربه کسب کنی؟</li></ul></article><article class="card"><ul><li>خانواده‌ات درباره کار تو در اسپوتا چه احساسی دارد؟</li><li>آخرین بار چه زمانی پیشنهادت جدی گرفته شد؟</li><li>برای فرزندت چه مهارتی را ارزشمند می‌دانی؟</li><li>اگر مدیریت فردا یک تغییر ایجاد کند، چه باشد؟</li><li>کدام مانع کاری را می‌توان با یک تغییر کوچک کم کرد؟</li></ul></article></div><p class="notice" style="margin-top:24px">ترکیب مصاحبه پیشنهادی اولیه: ۱۰ نفر تولید، ۵ نفر اداری، ۵ سرپرست، ۵ مدیر و ۵ نیروی جوان؛ نمونه‌گیری باید با تنوع واحد، جنسیت، سابقه، نوع شغل و شیفت متناسب شود. این تعداد برای کشف اولیه است، نه نظرسنجی آماری نماینده کل ۱۰۰۰ نفر.</p></div></section>''','نقشه اجرا')

pages['metrics.html']=page('metrics.html','''<header class="pagehero"><div class="shell"><div class="eyebrow">06 / GOVERNANCE & MEASUREMENT</div><h1>حاکمیت، شاخص‌ها و ریسک‌های اجرا</h1><p>برای آنکه طرح به کمپین ارتباطی یا مجموعه‌ای از فعالیت‌های مقطعی تبدیل نشود، باید مالکیت، تصمیم‌گیری، منابع و شاخص‌های اثر از ابتدا روشن باشند.</p></div></header><section class="section"><div class="shell"><div class="section-head"><div><div class="kicker">OPERATING MODEL</div><h2>تقسیم نقش‌ها</h2></div></div><div class="tablewrap"><table><thead><tr><th>نقش</th><th>مسئولیت اصلی</th><th>آنچه نباید به‌تنهایی بر عهده‌اش باشد</th></tr></thead><tbody><tr><td>مدیریت ارشد</td><td>حمایت راهبردی، رفع موانع، تأیید منابع و سیاست‌ها</td><td>مدیریت روزانه تمام فعالیت‌ها</td></tr><tr><td>منابع انسانی</td><td>مسیر شغلی، سیاست یادگیری، جابه‌جایی داخلی، ارزیابی، پرداخت و حاکمیت افراد</td><td>مالکیت تمام ارتباطات و روایت برند</td></tr><tr><td>مدیران و سرپرستان</td><td>شناسایی نیازها، فرصت رشد، مربی‌گری، ایمنی و تأیید اثر</td><td>مسدود کردن استعدادها در واحد خود</td></tr><tr><td>ارتباطات و برند</td><td>تجربه برند داخلی، معماری ارتباطات، مشارکت کارکنان، روایت واقعی، طراحی سیستم و سنجش تصویر برند کارفرمایی</td><td>جایگزینی HR یا وعده دادن به‌جای سازمان</td></tr><tr><td>عملیات و ایمنی</td><td>شرایط کار، مجوزهای آموزشی، ایمنی محیط و امکان‌پذیری برنامه‌ها</td><td>نادیده گرفتن خطر به‌خاطر جذابیت برنامه</td></tr><tr><td>حقوقی و مالی</td><td>قواعد پرداخت، بیمه، مسئولیت، حفاظت از داده و بودجه</td><td>ورود دیرهنگام پس از اعلام عمومی وعده‌ها</td></tr></tbody></table></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">MEASUREMENT</div><h2>داشبورد اثر</h2><p class="section-intro">اهداف عددی نهایی باید پس از اندازه‌گیری خط پایه و تأیید ظرفیت شرکت تعیین شوند. جدول زیر دسته شاخص‌ها را مشخص می‌کند، نه نتایج فعلی اسپوتا.</p></div></div><div class="grid three"><article class="card"><div class="iconbox">↗</div><h3>رشد و یادگیری</h3><p>تعداد مسیرهای رشد فعال، تکمیل آموزش، مهارت تأییدشده، ساعت یادگیری و گذرنامه‌های به‌روز.</p></article><article class="card"><div class="iconbox">⇄</div><h3>انتقال دانش</h3><p>مدرسان فعال، یادگیرندگان، تکمیل دوره، کیفیت آموزش، منتورینگ و دانش‌های کلیدی مستندسازی‌شده.</p></article><article class="card"><div class="iconbox">✓</div><h3>صدای کارکنان</h3><p>تعداد پیشنهادها، درصد بررسی‌شده، زمان پاسخ، درصد اجراشده و کیفیت توضیح تصمیم‌ها.</p></article><article class="card"><div class="iconbox">⌂</div><h3>خانواده و نسل آینده</h3><p>مشارکت خانواده، تکمیل دوره، نتیجه ارزیابی، تجربه عملی و دسترسی به فرصت‌های مرتبط.</p></article><article class="card"><div class="iconbox">◎</div><h3>برند کارفرمایی</h3><p>معرفی نیروی واجدشرایط، آگاهی و ترجیح کارفرما، پذیرش پیشنهاد شغلی و روایت‌های داوطلبانه کارکنان.</p></article><article class="card"><div class="iconbox">⚙</div><h3>اثر کسب‌وکار</h3><p>کاهش ضایعات و خطا، بهبود کیفیت، زمان انجام کار، ایده‌های اجراشده، جابه‌جایی داخلی و نگهداشت.</p></article></div><div class="section-head" style="margin-top:42px"><div><div class="kicker">RISK REGISTER</div><h2>ریسک‌هایی که باید از ابتدا مدیریت شوند</h2></div></div><div class="tablewrap"><table><thead><tr><th>ریسک</th><th>چرا مهم است؟</th><th>کنترل پیشنهادی</th></tr></thead><tbody><tr><td>جایگزین‌کردن مزایا به‌جای حقوق</td><td>می‌تواند به بی‌اعتمادی منجر شود.</td><td>شفافیت: برنامه توسعه مکمل جبران خدمت منصفانه است.</td></tr><tr><td>وعده استخدام تضمینی</td><td>ظرفیت شغلی و شرایط آینده قابل تضمین نیست.</td><td>مسیر اولویت‌دار بررسی، معیار روشن و اعلام محدودیت‌ها.</td></tr><tr><td>کار رایگان پنهان</td><td>آموزش خارج از ساعات کار می‌تواند حس بهره‌کشی ایجاد کند.</td><td>داوطلبانه بودن، جبران منصفانه و بررسی حقوقی.</td></tr><tr><td>گواهی کم‌اعتبار</td><td>ممکن است به اعتبار آکادمی لطمه بزند.</td><td>ارزیابی عملی، معیار مهارتی و همکاری با نهاد معتبر.</td></tr><tr><td>مقاومت مدیران میانی</td><td>ممکن است از دست دادن نیروی خوب را تهدید ببینند.</td><td>هدف‌گذاری برای توسعه افراد و شاخص‌های همکاری بین‌واحدی.</td></tr><tr><td>رقابت ناسالم بر سر امتیاز</td><td>تعداد فعالیت‌ها جای کیفیت را می‌گیرد.</td><td>پاداش بر اساس اثر تأییدشده، نه صرفاً حجم فعالیت.</td></tr><tr><td>حریم خصوصی و ایمنی</td><td>اطلاعات مهارتی، داده کارکنان و آموزش فنی حساس‌اند.</td><td>حداقل‌سازی داده، دسترسی کنترل‌شده، مجوز و پروتکل ایمنی.</td></tr></tbody></table></div><div class="callout"><strong>تصمیم‌هایی که مدیریت باید تأیید کند</strong><br>۱) حامی اجرایی و مالک برنامه؛ ۲) گروه پایلوت و واحدهای مشارکت‌کننده؛ ۳) زمان و بودجه هماهنگی؛ ۴) چارچوب پاداش و آموزش؛ ۵) قواعد مسیر شغلی و تحرک داخلی؛ ۶) امکان‌سنجی حقوقی و مالی آکادمی؛ ۷) شاخص‌های خط پایه و زمان بازبینی.</div><div class="section-head" style="margin-top:42px"><div><div class="kicker">EXECUTIVE SUMMARY</div><h2>درخواست تصمیم برای شروع</h2></div></div><div class="grid two"><article class="card dark"><h3>تصمیم پیشنهادی</h3><p>تأیید یک دوره کشف و پایلوت ۹۰ روزه برای سنجش امکان‌پذیری مدل در سازمان حدوداً ۱۰۰۰ نفره؛ بدون تعهد زودهنگام به ساخت اپلیکیشن یا آکادمی کامل.</p></article><article class="card"><h3>خروجی قابل ارائه در پایان ۹۰ روز</h3><p>نقشه مهارت‌ها، نیازهای رشد، فرایند پیگیری پیشنهادها، گزارش آموزش داخلی، برآورد هزینه، ریسک‌ها و توصیه مستند برای توسعه یا اصلاح طرح.</p></article></div></div></section>''','شاخص‌ها و حاکمیت')

